let language='ru',dictionary={},inverse={},folded={},fragments=null;const originals=new WeakMap();
export const getLanguage=()=>language;
export function configureTranslations(values){dictionary=values;folded=Object.fromEntries(Object.entries(values).map(([k,v])=>[k.toLocaleLowerCase('ru'),v]));inverse=Object.fromEntries(Object.entries(values).filter(([a,b])=>a!==b).map(([a,b])=>[b,a]));const keys=Object.keys(values).filter(k=>k.length<180).sort((a,b)=>b.length-a.length);fragments=new RegExp(keys.map(k=>k.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')).join('|'),'gi');}
export const englishText=value=>dictionary[String(value??'').trim()]??String(value??'');
export function setLanguage(value){language=value==='en'?'en':'ru';if(typeof document!=='undefined'&&document.documentElement)document.documentElement.lang=language;}
export function translateText(value){const raw=String(value??'');if(language==='ru')return raw;const key=raw.trim(),normalized=key.replace(/\s+/g,' '),translated=dictionary[key]??dictionary[normalized]??folded[normalized.toLocaleLowerCase('ru')];if(translated!==undefined)return raw.replace(key,key===key.toUpperCase()&&/[А-ЯЁ]/.test(key)?translated.toUpperCase():translated);return fragments?raw.replace(fragments,m=>dictionary[m]??folded[m.toLocaleLowerCase('ru')]??m):raw;}
const unescape=s=>s.replace(/&(?:amp|lt|gt|quot|#39|nbsp);/g,m=>({'&amp;':'&','&lt;':'<','&gt;':'>','&quot;':'"','&#39;':"'",'&nbsp;':' '})[m]);
const escape=s=>s.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'})[c]);
export function translateMarkup(markup){if(language==='ru')return String(markup);return String(markup).split(/(<[^>]*>)/g).map(part=>part.startsWith('<')?part.replace(/\b(aria-label|title|placeholder|data-tip|alt)="([^"]*)"/g,(_,key,val)=>`${key}="${escape(translateText(unescape(val)))}"`):escape(translateText(unescape(part)))).join('');}
// Static shell only. Dynamic content is translated at its rendering boundary.
export function translateShell(root=document){if(!root.createTreeWalker)return;const walk=root.createTreeWalker(root.body,4);let node;while((node=walk.nextNode())){if(['SCRIPT','STYLE','SVG'].includes(node.parentElement?.tagName))continue;let source=originals.get(node);if(source===undefined){source=node.nodeValue;originals.set(node,source);}node.nodeValue=translateText(source);}for(const node of root.querySelectorAll('[aria-label],[title],[placeholder],[data-tip]')){for(const key of ['aria-label','title','placeholder','data-tip']){if(!node.hasAttribute(key))continue;let record=originals.get(node);if(!record){record={};originals.set(node,record);}record[key]??=node.getAttribute(key);node.setAttribute(key,translateText(record[key]));}}}
export function untranslatedText(value){return /[А-Яа-яЁё]/.test(translateText(value));}
